def string_expansion(s):
    result = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            count = int(s[i])
            i += 1
            while i < len(s) and s[i].isalpha():
                result.append(s[i] * count)
                i += 1
        else:
            i += 1
    return ''.join(result)
